import { motion, Transition } from "framer-motion"

const pageVariants = {
  initial: {
    opacity: 0,
    y: 40
  },
  animate: {
    opacity: 1,
    y: 0
  },
  exit: {
    opacity: 0,
    y: -40
  }
}

const pageTransition: Transition = {
  duration: 0.35,
  ease: "easeInOut"
}

export default function PageTransition({ children }: any) {
  return (
    <motion.div
      variants={pageVariants}
      initial="initial"
      animate="animate"
      exit="exit"
      transition={pageTransition}
    >
      {children}
    </motion.div>
  )
}
